// Synthetic EVENOTA bundles for tests. No Even firmware is involved: payloads
// are generated bytes with stock-shaped headers. `rawBundle` deliberately
// skips every guard so tests can build the broken inputs the guards must catch.

import { asciiBytes, writeFixedString, writeU32 } from '../bytes.ts';
import {
  COMPONENT_HEADER_SIZE,
  COMPONENT_MAGIC,
  EVENOTA_MAGIC,
  EVENOTA_TRAILER,
  MAIN_LOAD_ADDRESS,
  MAIN_PATH,
  PREAMBLE_SIZE,
  TOC_ENTRY_SIZE,
  TOC_OFFSET,
  TRAILER_SIZE,
} from '../constants.ts';
import { crc32, crc32cMsb } from '../crc.ts';

/** Deterministic filler (xorshift32), so CRCs are reproducible. */
export function filler(length: number, seed = 0x1234567): Uint8Array {
  const out = new Uint8Array(length);
  let x = seed >>> 0 || 1;
  for (let i = 0; i < length; i++) {
    x ^= x << 13;
    x >>>= 0;
    x ^= x >>> 17;
    x ^= x << 5;
    x >>>= 0;
    out[i] = x & 0xff;
  }
  return out;
}

export interface AppOptions {
  size?: number;
  sp?: number;
  reset?: number;
  /** Version written as standalone NUL-bracketed strings at aligned offsets. */
  version?: string;
  versionCopies?: number;
}

/** A raw app image as linked at 0x438000: vector table, then filler. */
export function syntheticApp(options: AppOptions = {}): Uint8Array {
  const size = options.size ?? 0x4000;
  const app = filler(size);
  writeU32(app, 0, options.sp ?? 0x2007fb00);
  writeU32(app, 4, options.reset ?? MAIN_LOAD_ADDRESS + 0x201);
  for (let i = 8; i < 0x40; i += 4) writeU32(app, i, MAIN_LOAD_ADDRESS + 0x301);
  if (options.version) {
    const v = asciiBytes(options.version);
    const copies = options.versionCopies ?? 3;
    // Payload offsets = app offsets + 0x20, both word-aligned.
    for (let n = 0; n < copies; n++) {
      const at = 0x1000 + n * 0x100;
      app.fill(0, at - 4, at + v.length + 4);
      app.set(v, at);
    }
    // Decoys that must not be touched: a git-describe string and an unaligned copy.
    const decoy = asciiBytes(`master:v${options.version}-0-gb79923a139f5`);
    app.fill(0, 0x2000 - 4, 0x2000 + decoy.length + 4);
    app.set(decoy, 0x2000);
    app.fill(0, 0x2100, 0x2100 + v.length + 8);
    app.set(v, 0x2101);
  }
  return app;
}

/** Preamble + app, as a stock main payload. `patch` edits it before the CRC is computed. */
export function syntheticMainPayload(
  app: Uint8Array,
  patch?: (payload: Uint8Array) => void,
): Uint8Array {
  const payload = new Uint8Array(PREAMBLE_SIZE + app.length);
  writeU32(payload, 0, ((0x04 << 24) | payload.length) >>> 0);
  writeU32(payload, 0x10, 0xcb);
  writeU32(payload, 0x14, MAIN_LOAD_ADDRESS);
  payload.set(app, PREAMBLE_SIZE);
  patch?.(payload);
  writeU32(payload, 4, crc32(payload.subarray(8)));
  return payload;
}

export interface RawComponent {
  entryId: number;
  type: number;
  storageType?: number;
  path: string;
  payload: Uint8Array;
  /** Override the CRC written to the TOC / header (default: the correct one). */
  tocCrc?: number;
  headerCrc?: number;
}

export interface RawHeader {
  version?: string;
  buildDate?: string;
  buildTime?: string;
}

/** Assembles an EVENOTA bundle byte-for-byte as stock does, with no guards. */
export function rawBundle(
  components: RawComponent[],
  header: RawHeader = {},
): Uint8Array {
  const tocEnd = TOC_OFFSET + components.length * TOC_ENTRY_SIZE;
  let size = tocEnd + TRAILER_SIZE;
  for (const c of components) size += COMPONENT_HEADER_SIZE + c.payload.length;
  const out = new Uint8Array(size);
  out.set(EVENOTA_MAGIC, 0);
  writeU32(out, 8, components.length);
  writeFixedString(out, 0x10, 16, header.buildDate ?? '2026-07-06');
  writeFixedString(out, 0x20, 16, header.buildTime ?? '21:39:36');
  writeFixedString(out, 0x30, 16, header.version ?? 's200_v2.2.6.10');
  out.set(EVENOTA_TRAILER, tocEnd);
  let offset = tocEnd + TRAILER_SIZE;
  components.forEach((c, i) => {
    const crc = crc32cMsb(c.payload);
    const t = TOC_OFFSET + i * TOC_ENTRY_SIZE;
    writeU32(out, t, c.entryId);
    writeU32(out, t + 4, offset);
    writeU32(out, t + 8, COMPONENT_HEADER_SIZE + c.payload.length);
    writeU32(out, t + 12, c.tocCrc ?? crc);
    writeU32(out, offset + 0x08, c.payload.length);
    writeU32(out, offset + 0x0c, c.headerCrc ?? crc);
    writeU32(out, offset + 0x14, COMPONENT_MAGIC);
    writeU32(out, offset + 0x18, 0xffffffff);
    writeU32(out, offset + 0x1c, 0xffffffff);
    writeU32(out, offset + 0x24, c.type);
    writeU32(out, offset + 0x28, c.storageType ?? 3);
    writeU32(out, offset + 0x2c, 0xffffffff);
    writeFixedString(out, offset + 0x30, 0x50, c.path);
    out.set(c.payload, offset + COMPONENT_HEADER_SIZE);
    offset += COMPONENT_HEADER_SIZE + c.payload.length;
  });
  return out;
}

export function mainComponent(payload: Uint8Array, entryId = 6): RawComponent {
  return { entryId, type: 0, path: MAIN_PATH, payload };
}

/** A main-only bundle around `payload`, as `packMain` would produce. */
export function mainOnly(payload: Uint8Array, header?: RawHeader): Uint8Array {
  return rawBundle([mainComponent(payload)], header);
}

/**
 * A stock-shaped bundle: codec, EM9305, touch, case, bootloader, main (ids 1–6).
 * `withBootloader: false` gives the five-component shape of 2.2.0.24 / 2.2.4.34
 * (main is then entry 5).
 */
export function syntheticStock(
  version = '2.2.6.10',
  app?: Uint8Array,
  withBootloader = true,
): Uint8Array {
  const main = syntheticMainPayload(
    app ?? syntheticApp({ version, size: 0x8000 }),
  );
  const others: RawComponent[] = [
    {
      entryId: 1,
      type: 4,
      path: 'firmware/codec.bin',
      payload: filler(3001, 1),
    },
    {
      entryId: 2,
      type: 5,
      path: 'firmware/ble_em9305.bin',
      payload: filler(2003, 2),
    },
    {
      entryId: 3,
      type: 3,
      path: 'firmware/touch.bin',
      payload: filler(1005, 3),
    },
    { entryId: 4, type: 6, path: 'firmware/box.bin', payload: filler(1007, 4) },
  ];
  if (withBootloader)
    others.push({
      entryId: 5,
      type: 1,
      path: 'ota/s200_bootloader.bin',
      payload: filler(2009, 5),
    });
  return rawBundle([...others, mainComponent(main, others.length + 1)], {
    version: `s200_v${version}`,
  });
}
